mapper.update:
UPDATE `planat`.`contact_tokens`
SET `user_agent` = #{contactToken.userAgent},
    `is_used`    = #{contactToken.isUsed},
    `created_at` = #{contactToken.createdAt},
    `expires_at` = #{contactToken.expiresAt}
WHERE `contact_first` = #{contactToken.contactFirst}
  AND `contact_second` = #{contactToken.contactSecond}
  AND `contact_third` = #{contactToken.contactThird}
  AND `code` = #{contactToken.code}
  AND `salt` = #{contactToken.salt}
LIMIT 1

mapper.select:
SELECT `contact_first`  AS `contactFirst`,
       `contact_second` AS `contactSecond`,
       `contact_third`  AS `contactThird`,
       `code`           AS `code`,
       `salt`           AS `salt`,
       `user_agent`     AS `userAgent`,
       `is_used`        AS `isUsed`,
       `created_at`     AS `createdAt`,
       `expires_at`     AS `expiresAt`
FROM `planat`.`contact_tokens`
WHERE `contact_first` = #{contactFirst}
  AND `contact_second` = #{contactSecond}
  AND `contact_third` = #{contactThird}
  AND `code` = #{code}
  AND `salt` = #{salt}
LIMIT 1
